package com.yeyamo_mobile.api.place_service.dto;
import java.time.Instant;import java.util.List;import java.util.UUID;import com.yeyamo_mobile.api.place_service.models.Place;
public record AdminPlaceResponse(UUID id,String name,String slug,UUID partnerId,Reference category,Reference region,Reference city,Reference district,String description,Coordinates coordinates,String address,String phone,String website,String status,boolean verified,List<PlaceMediaResponse> media,List<PlaceScheduleResponse> schedules,Instant createdAt,Instant updatedAt){
 public record Reference(Long id,String name){} public record Coordinates(double latitude,double longitude){}
 public static AdminPlaceResponse from(Place p){return new AdminPlaceResponse(p.getId(),p.getName(),p.getSlug(),p.getPartnerId(),p.getCategory()==null?null:new Reference(p.getCategory().getId(),p.getCategory().getName()),new Reference(p.getRegion().getId(),p.getRegion().getName()),new Reference(p.getCity().getId(),p.getCity().getName()),p.getDistrict()==null?null:new Reference(p.getDistrict().getId(),p.getDistrict().getName()),p.getDescription(),new Coordinates(p.getLatitude(),p.getLongitude()),p.getAddress(),p.getPhone(),p.getWebsite(),p.getStatus().name(),p.isVerified(),p.getMedia().stream().map(PlaceMediaResponse::from).toList(),p.getSchedules().stream().map(PlaceScheduleResponse::from).toList(),p.getCreatedAt(),p.getUpdatedAt());}
}
